const fs = require('fs');
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find the End of Central Directory record
let eocdOffset = -1;
for (let i = buf.length - 4; i >= 0; i--) {
  if (buf.readUInt32LE(i) === 0x06054b50) {
    eocdOffset = i;
    break;
  }
}

const cdOffset = buf.readUInt32LE(eocdOffset + 16);
const cdSize = buf.readUInt32LE(eocdOffset + 12);
const cdCount = buf.readUInt16LE(eocdOffset + 10);

// Parse central directory to find word/document.xml
let offset = cdOffset;
for (let i = 0; i < cdCount; i++) {
  const sig = buf.readUInt32LE(offset);
  const compMethod = buf.readUInt16LE(offset + 10);
  const compSize = buf.readUInt32LE(offset + 20);
  const uncompSize = buf.readUInt32LE(offset + 24);
  const nameLen = buf.readUInt16LE(offset + 28);
  const extraLen = buf.readUInt16LE(offset + 30);
  const commentLen = buf.readUInt16LE(offset + 32);
  const localHeaderOffset = buf.readUInt32LE(offset + 42);
  const name = buf.toString('utf8', offset + 46, offset + 46 + nameLen);

  if (name === 'word/document.xml') {
    // Read from local file header
    const lh = localHeaderOffset;
    const lhNameLen = buf.readUInt16LE(lh + 26);
    const lhExtraLen = buf.readUInt16LE(lh + 28);
    const dataStart = lh + 30 + lhNameLen + lhExtraLen;
    const compData = buf.slice(dataStart, dataStart + compSize);

    const zlib = require('zlib');
    let xmlStr;
    if (compMethod === 0) {
      xmlStr = compData.toString('utf8');
    } else {
      xmlStr = zlib.inflateRawSync(compData).toString('utf8');
    }

    // Extract text from w:t elements
    const regex = /<w:t[^>]*?>([^<]*)<\/w:t>/g;
    let match;
    let fullText = [];
    let currentPara = '';
    // Split by paragraph markers
    const paras = xmlStr.split(/<\/w:p>/);
    for (const para of paras) {
      const texts = [];
      let m;
      const re = /<w:t[^>]*?>([^<]*)<\/w:t>/g;
      while ((m = re.exec(para)) !== null) {
        texts.push(m[1]);
      }
      if (texts.length > 0) {
        fullText.push(texts.join(''));
      }
    }
    console.log(fullText.join('\n'));
    break;
  }

  offset += 46 + nameLen + extraLen + commentLen;
}
